  uint32_t reg_val;
  uint32_t mask;

  if (pin >= LS2K300_GPIO_NPINS || function > LS2K300_PINCTRL_FUNC_MASK)
    {
      return -EINVAL;
    }

  reg_offset = (pin / PINS_PER_REG) * 4;
  bit_offset = (pin % PINS_PER_REG) * 2;

  mask = LS2K300_PINCTRL_FUNC_MASK << bit_offset;

  reg_val = getreg32(priv->base + reg_offset);
  reg_val &= ~mask;
  reg_val |= (function & LS2K300_PINCTRL_FUNC_MASK) << bit_offset;
  putreg32(reg_val, priv->base + reg_offset);

  return OK;
}

