static int ls2k300_pinctrl_select_gpio(FAR struct pinctrl_dev_s *dev,
                                       uint32_t pin)
{
  return ls2k300_pinctrl_set_function(dev, pin, LS2K300_PINCTRL_FUNC_GPIO);
}

static const struct pinctrl_ops_s g_pinctrl_ops =
{
  .set_function = ls2k300_pinctrl_set_function,
  .set_strength = ls2k300_pinctrl_set_strength,
  .set_driver   = ls2k300_pinctrl_set_driver,
  .set_slewrate = ls2k300_pinctrl_set_slewrate,
  .select_gpio  = ls2k300_pinctrl_select_gpio,
};

static struct ls2k300_pinctrl_dev_s g_pinctrl_priv =
{
  .dev =
    {
      .ops = &g_pinctrl_ops,
    },
  .base = PHYS_TO_UNCACHED(LS2K300_PINCTRL_BASE),
};

int ls2k300_pinctrl_initialize(void)
{
  int ret;

  ret = pinctrl_register(&g_pinctrl_priv.dev, 0);
  if (ret < 0)
    {
      _err("ERROR: pinctrl_register failed: %d\n", ret);
      return ret;
    }

  return OK;
}

int ls2k300_pinctrl_set_pinmux(uint32_t reg_offset, uint32_t value,
                               uint32_t mask)
{
  uint32_t reg_val;

  reg_val = getreg32(g_pinctrl_priv.base + reg_offset);
  reg_val &= ~mask;
  reg_val |= value & mask;
  putreg32(reg_val, g_pinctrl_priv.base + reg_offset);

  return OK;
}

uint32_t ls2k300_pinctrl_get_pinmux(uint32_t reg_offset, uint32_t mask)
{
  return getreg32(g_pinctrl_priv.base + reg_offset) & mask;
}

