35	 * Pre-processor Definitions
36	 ****************************************************************************/
37	
38	#define PWM_DEVICE          "/dev/pwm2"
39	#define PWM_GPIO            88
40	#define PWM_FUNCTION        2       /* SECOND_FUNC for PWM output */
41	#define PWM_FREQUENCY       1000    /* 1kHz */
42	
43	/* Breathing parameters */
44	
45	#define BREATH_STEPS        100     /* duty steps per ramp */
46	#define BREATH_DELAY_MS     30      /* ms per step */
47	#define BREATH_CYCLES       3       /* number of full breath cycles */
48	
49	/* NuttX PWM duty range: 0 ~ 65536 */
50	
51	#define PWM_DUTY_MAX        65536
52	
53	/****************************************************************************
54	 * Private Functions
55	 ****************************************************************************/
56	
57	static int pwm_pinctrl_setup(void)
58	{
59	  struct pinctrl_param_s param;
60	  int fd;
61	  int ret;
62	
63	  printf("[PWM] Setting GPIO%d to function %d (PWM2)...\n",
64	         PWM_GPIO, PWM_FUNCTION);
65	
66	  fd = open("/dev/pinctrl0", O_RDWR);
67	  if (fd < 0)
68	    {
69	      printf("[PWM] ERROR: open /dev/pinctrl0 failed: %d\n", errno);
70	      return -errno;
71	    }
72	
73	  param.pin = PWM_GPIO;
74	  param.para.function = PWM_FUNCTION;
75	  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
76	  if (ret < 0)
77	    {
78	      printf("[PWM] ERROR: PINCTRLC_SETFUNCTION GPIO%d func=%d failed: %d\n",
79	             PWM_GPIO, PWM_FUNCTION, errno);
80	      close(fd);
81	      return -errno;
82	    }
83	
84	  printf("[PWM] GPIO%d set to function %d OK\n", PWM_GPIO, PWM_FUNCTION);
85	  close(fd);
86	  return OK;
87	}
