89	/****************************************************************************
90	 * Public Functions
91	 ****************************************************************************/
92	
93	int test_pwm(void)
94	{
95	  int fd;
96	  int ret;
97	  struct pwm_info_s info;
98	  int cycle;
99	  int step;
100	  uint32_t duty;
101	
102	  printf("[PWM] === Hardware PWM Breathing LED Test ===\n");
103	  printf("[PWM] Device: %s (GPIO%d, second function)\n",
104	         PWM_DEVICE, PWM_GPIO);
105	  printf("[PWM] Frequency: %dHz\n", PWM_FREQUENCY);
106	  printf("[PWM] Breathing: %d steps, %dms/step, %d cycles\n\n",
107	         BREATH_STEPS, BREATH_DELAY_MS, BREATH_CYCLES);
108	
109	  /* Configure GPIO88 pinmux to PWM function (MUST do this first!) */
110	
111	  ret = pwm_pinctrl_setup();
112	  if (ret < 0)
113	    {
114	      printf("[PWM] ERROR: pinctrl setup failed\n");
115	      return ret;
116	    }
117	
118	  /* Open PWM device */
119	
120	  fd = open(PWM_DEVICE, O_RDONLY);
121	  if (fd < 0)
122	    {
123	      printf("[PWM] ERROR: open %s failed: %d\n", PWM_DEVICE, errno);
124	      return -errno;
125	    }
126	
127	  printf("[PWM] %s opened, fd=%d\n", PWM_DEVICE, fd);
128	
129	  /* Configure PWM */
130	
131	  info.frequency = PWM_FREQUENCY;
132	  info.duty      = 0;
133	
134	  ret = ioctl(fd, PWMIOC_SETCHARACTERISTICS,
135	              (unsigned long)(uintptr_t)&info);
136	  if (ret < 0)
137	    {
138	      printf("[PWM] ERROR: PWMIOC_SETCHARACTERISTICS failed: %d\n", errno);
139	      close(fd);
140	      return -errno;
141	    }
142	
143	  /* Start PWM */
144	
145	  ret = ioctl(fd, PWMIOC_START, 0);
146	  if (ret < 0)
147	    {
148	      printf("[PWM] ERROR: PWMIOC_START failed: %d\n", errno);
149	      close(fd);
150	      return -errno;
151	    }
152	
153	  printf("[PWM] PWM started, breathing...\n\n");
154	
155	  /* Breathing loop */
156	
157	  for (cycle = 0; cycle < BREATH_CYCLES; cycle++)
158	    {
159	      printf("[PWM] Cycle %d/%d\n", cycle + 1, BREATH_CYCLES);
160	
161	      /* Ramp up: 0% → 100% */
162	
163	      for (step = 0; step <= BREATH_STEPS; step++)
164	        {
165	          duty = (uint32_t)step * PWM_DUTY_MAX / BREATH_STEPS;
166	          info.frequency = PWM_FREQUENCY;
167	          info.duty      = duty;
168	
169	          ret = ioctl(fd, PWMIOC_SETCHARACTERISTICS,
170	                      (unsigned long)(uintptr_t)&info);
171	          if (ret < 0)
172	            {
173	              printf("[PWM] ERROR: set duty failed: %d\n", errno);
174	              break;
175	            }
176	
177	          up_mdelay(BREATH_DELAY_MS);
178	        }
179	
180	      /* Ramp down: 100% → 0% */
181	
182	      for (step = BREATH_STEPS; step >= 0; step--)
183	        {
184	          duty = (uint32_t)step * PWM_DUTY_MAX / BREATH_STEPS;
185	          info.frequency = PWM_FREQUENCY;
