/****************************************************************************
 * apps/examples/ls_driver_test/test_uart2.c
 *
 * UART2 byte send/receive test for LoongArch 2K300 (Hummingbird board).
 *
 * Function:
 *   - UART2 on GPIO44 (TX) / GPIO45 (RX), muxed to FIRST_FUNC (function=1)
 *   - 16550-compatible UART, 8N1, 115200 baud
 *   - Send a banner, then echo any received byte back to the sender
 *
 * Hardware:
 *   - UART2 controller base: 0x16100800 (non-cached: 0x8000000016100800)
 *   - APB reference clock: 200 MHz
 *   - Register access width: 8-bit (16550 byte registers)
 *
 * NOTE: This is a bare-metal register-level driver that talks to the UART2
 *       controller directly (not via /dev/ttySx). Pinmux is asserted from the
 *       application layer via /dev/pinctrl0, because other drivers may have
 *       overwritten the GPIO44/45 function selection during boot.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <stdio.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <string.h>

#include <nuttx/arch.h>
#include <nuttx/pinctrl/pinctrl.h>

#include "ls_driver_test.h"

/* The 16550 register bit/offset definitions live in the arch header. */

#include <arch/ls2k300/hardware/ls2k300_uart.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* UART2 controller: physical 0x16100800 -> non-cached alias. */

#define UART2_BASE              (0x8000000000000000UL | 0x16100800UL)

/* 8-bit register access (16550 byte registers, see ls2k300_serial.c). */

#define UART_REG8(off)          (*(volatile uint8_t *)(UART2_BASE + (off)))

/* Pin assignment: GPIO44=TX, GPIO45=RX, both FIRST_FUNC (mode 0x1). */

#define UART2_TX_GPIO           44
#define UART2_RX_GPIO           45
#define UART2_FUNCTION          1       /* LS_PINMUX_MODE_AS_FIRST_FUNC */

/* APB reference clock is 200 MHz (LS2K300_APB_FREQ = 200, in MHz). */

#define UART_REF_CLK            (200 * 1000000)
#define UART_BAUD               115200

/* LSR wait timeout (cycles). Kept large enough for slow startup. */

#define UART_LSR_TIMEOUT        1000000

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int uart2_pinctrl_setup(void);
static void uart2_init(void);
static void uart2_putc(char ch);
static int  uart2_getc(char *ch);

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: uart2_pinctrl_setup
 *
 * Description:
 *   Mux GPIO44/GPIO45 to FIRST_FUNC (function=1) for UART2 TX/RX. Done from
 *   the application layer via /dev/pinctrl0 because the bringup pinmux may be
 *   overwritten by other drivers later in the boot sequence.
 *
 ****************************************************************************/

static int uart2_pinctrl_setup(void)
{
  struct pinctrl_param_s param;
  int fd;
  int ret;

  printf("[UART2] Setting GPIO%d(TX)/GPIO%d(RX) to function %d...\n",
         UART2_TX_GPIO, UART2_RX_GPIO, UART2_FUNCTION);

  fd = open("/dev/pinctrl0", O_RDWR);
  if (fd < 0)
    {
      printf("[UART2] ERROR: open /dev/pinctrl0 failed: %d\n", errno);
      return -errno;
    }

  /* TX pin */

  param.pin = UART2_TX_GPIO;
  param.para.function = UART2_FUNCTION;
  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
  if (ret < 0)
    {
      printf("[UART2] ERROR: SETFUNCTION GPIO%d failed: %d\n",
             UART2_TX_GPIO, errno);
      close(fd);
      return -errno;
    }

  /* RX pin */

  param.pin = UART2_RX_GPIO;
  param.para.function = UART2_FUNCTION;
  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
  if (ret < 0)
    {
      printf("[UART2] ERROR: SETFUNCTION GPIO%d failed: %d\n",
             UART2_RX_GPIO, errno);
      close(fd);
      return -errno;
    }

  printf("[UART2] Pinmux OK (GPIO%d/GPIO%d -> func %d)\n",
         UART2_TX_GPIO, UART2_RX_GPIO, UART2_FUNCTION);
  close(fd);
  return OK;
}

/****************************************************************************
 * Name: uart2_init
 *
 * Description:
 *   Initialize the UART2 controller for 8N1 at UART_BAUD. The init sequence
 *   mirrors ls2k300_serial.c: disable IRQs, set DLAB, program the baud
 *   divisor, switch to 8N1, then enable & flush the FIFOs.
 *
 ****************************************************************************/

static void uart2_init(void)
{
  uint32_t div_val = (UART_REF_CLK + (UART_BAUD * 8)) / (UART_BAUD * 16);

  printf("[UART2] Init: baud=%d, 8N1, divisor=%lu\n",
         UART_BAUD, (unsigned long)div_val);

  /* Disable all UART interrupts during configuration. */

  UART_REG8(UART_IER_OFFSET) = 0;

  /* Enter Divisor Latch Access mode to program the baud divisor. */

  UART_REG8(UART_LCR_OFFSET) = UART_LCR_DLAB;
  UART_REG8(UART_DLL_OFFSET) = (uint8_t)(div_val & 0xff);
  UART_REG8(UART_DLH_OFFSET) = (uint8_t)((div_val >> 8) & 0xff);

  /* 8 data bits, no parity, 1 stop bit (0x03); this also clears DLAB. */

  UART_REG8(UART_LCR_OFFSET) = UART_LCR_WLEN8;

  /* Enable FIFO, reset RX/TX, trigger interrupt at 1 byte. */

  UART_REG8(UART_FCR_OFFSET) = UART_FCR_FIFOEN | UART_FCR_RXRST |
                               UART_FCR_TXRST | UART_FCR_RXTRG_1;

  /* Assert DTR + RTS (modem control; harmless if unused). */

  UART_REG8(UART_MCR_OFFSET) = UART_MCR_DTR | UART_MCR_RTS;
}

/****************************************************************************
 * Name: uart2_putc
 *
 * Description:
 *   Send one byte. Wait for the THR-empty (THRE) bit in LSR before writing.
 *
 ****************************************************************************/

static void uart2_putc(char ch)
{
  volatile uint32_t timeout = UART_LSR_TIMEOUT;

  while ((UART_REG8(UART_LSR_OFFSET) & UART_LSR_THRE) == 0)
    {
      if (--timeout == 0)
        {
          printf("[UART2] TX timeout on byte 0x%02x\n", (uint8_t)ch);
          return;
        }
    }

  UART_REG8(UART_THR_OFFSET) = (uint8_t)ch;
}

/****************************************************************************
 * Name: uart2_getc
 *
 * Description:
 *   Poll for one received byte. Returns 1 on success (byte stored in *ch),
 *   0 if no data arrived within the timeout window.
 *
 ****************************************************************************/

static int uart2_getc(char *ch)
{
  volatile uint32_t timeout = UART_LSR_TIMEOUT;

  while ((UART_REG8(UART_LSR_OFFSET) & UART_LSR_DR) == 0)
    {
      if (--timeout == 0)
        {
          return 0;
        }
    }

  *ch = (char)UART_REG8(UART_RBR_OFFSET);
  return 1;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: test_uart2
 *
 * Description:
 *   - Mux GPIO44/GPIO45 to UART2 first function
 *   - Initialize the UART2 controller (8N1, 115200)
 *   - Transmit a banner string over UART2
 *   - Echo loop: every byte received on UART2 is echoed back and also
 *     reported on the console, so you can confirm round-trip with a
 *     USB-TTL connected to GPIO44(TX)/GPIO45(RX)
 *
 ****************************************************************************/

int test_uart2(void)
{
  static const char banner[] =
    "\r\n=== LS2K300 UART2 Echo Test (GPIO44 TX / GPIO45 RX) ===\r\n"
    "Type characters, they will be echoed back.\r\n";
  const char *p;
  char ch;
  int ret;

  printf("[UART2] === UART2 Byte Send/Receive Test ===\n");
  printf("[UART2] Pins: GPIO%d(TX) / GPIO%d(RX), function %d\n",
         UART2_TX_GPIO, UART2_RX_GPIO, UART2_FUNCTION);
  printf("[UART2] Config: 8N1 @ %d baud\n\n", UART_BAUD);

  /* Step 1: pinmux (MUST do this first, before touching the controller). */

  ret = uart2_pinctrl_setup();
  if (ret < 0)
    {
      printf("[UART2] ERROR: pinctrl setup failed: %d\n", ret);
      return ret;
    }

  /* Step 2: controller init. */

  uart2_init();

  /* Step 3: transmit the banner. */

  printf("[UART2] Sending banner (%d bytes)...\n", (int)sizeof(banner) - 1);
  for (p = banner; *p != '\0'; p++)
    {
      uart2_putc(*p);
    }

  printf("[UART2] Banner sent. Entering echo loop (send bytes to UART2).\n");
  printf("[UART2] Console will print each byte received. "
         "Run a few seconds then exit via NSH.\n\n");

  /* Step 4: echo loop. Echo each received byte back over UART2 and also
   *         log it on the console. Bounded to 64 bytes so the test exits
   *         on its own if nothing is connected. */

  int received = 0;
  while (received < 64)
    {
      if (uart2_getc(&ch))
        {
          printf("[UART2] RX: 0x%02x ('%c')\n", (uint8_t)ch,
                 (ch >= 32 && ch < 127) ? ch : '.');

          /* Echo back to the UART2 sender. */

          uart2_putc(ch);

          /* Exit on CR / LF so the test terminates cleanly. */

          if (ch == '\r' || ch == '\n')
            {
              uart2_putc('\n');
              break;
            }

          received++;
        }
      else
        {
          /* No byte yet; yield so we don't peg the CPU. */

          up_mdelay(10);
        }
    }

  printf("\n[UART2] Done. Received %d bytes.\n", received);
  return OK;
}

