200	/****************************************************************************
201	 * Private Functions
202	 ****************************************************************************/
203	
204	static uint32_t up_serialin(struct up_dev_s *priv, int offset)
205	{
206	  return getreg8(priv->uartbase + offset);
207	}
208	
209	static void up_serialout(struct up_dev_s *priv, int offset, uint32_t value)
210	{
211	  putreg8((uint8_t)value, priv->uartbase + offset);
212	}
213	
214	static void up_restoreuartint(struct up_dev_s *priv, uint8_t im)
215	{
216	  irqstate_t flags = spin_lock_irqsave(&priv->lock);
217	
218	  priv->im = im;
219	  up_serialout(priv, UART_IER_OFFSET, im);
220	
221	  spin_unlock_irqrestore(&priv->lock, flags);
222	}
223	
224	static void up_disableuartint(struct up_dev_s *priv, uint8_t *im)
225	{
226	  irqstate_t flags = spin_lock_irqsave(&priv->lock);
227	
228	  if (im)
229	    {
230	      *im = priv->im;
231	    }
232	
233	  priv->im = 0;
234	  up_serialout(priv, UART_IER_OFFSET, 0);
235	  spin_unlock_irqrestore(&priv->lock, flags);
236	}
237	
238	static int up_setup(struct uart_dev_s *dev)
239	{
240	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
241	  uint32_t uart_ref_clk = LS2K300_APB_FREQ * 1000000;
242	  uint32_t div_val = (uart_ref_clk + (priv->baud * 8)) / (priv->baud * 16);
243	
244	  up_serialout(priv, UART_LCR_OFFSET, UART_LCR_DLAB);
245	  up_serialout(priv, UART_DLL_OFFSET, div_val & 0xff);
246	  up_serialout(priv, UART_DLH_OFFSET, (div_val >> 8) & 0xff);
247	  up_serialout(priv, UART_LCR_OFFSET, UART_LCR_WLEN8);
248	  up_serialout(priv, UART_FCR_OFFSET,
249	               UART_FCR_FIFOEN | UART_FCR_RXRST | UART_FCR_TXRST |
250	               UART_FCR_RXTRG_1);
251	
252	  return OK;
253	}
254	
255	static void up_shutdown(struct uart_dev_s *dev)
256	{
257	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
258	  up_disableuartint(priv, NULL);
259	}
260	
261	static int up_attach(struct uart_dev_s *dev)
262	{
263	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
264	  int ret;
265	
266	  up_serialout(priv, UART_IER_OFFSET,
267	               UART_IER_ERBFI | UART_IER_ETBEI);
268	
269	  ret = irq_attach(priv->irq, up_interrupt, dev);
270	  if (ret == OK)
271	    {
272	      up_enable_irq(priv->irq);
273	    }
274	
275	  return ret;
276	}
277	
278	static void up_detach(struct uart_dev_s *dev)
279	{
280	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
281	  up_disable_irq(priv->irq);
282	  irq_detach(priv->irq);
283	}
284	
285	static int up_interrupt(int irq, void *context, void *arg)
286	{
287	  struct uart_dev_s *dev = (struct uart_dev_s *)arg;
288	  struct up_dev_s   *priv = (struct up_dev_s *)dev->priv;
289	  uint32_t           status;
290	  int                passes;
291	
292	  for (passes = 0; passes < 256; passes++)
293	    {
294	      status = up_serialin(priv, UART_IIR_OFFSET);
295	
296	      if ((status & UART_IIR_NOINT) || status == 0)
297	        {
298	          break;
299	        }
300	
301	      if ((status & 0x0e) == UART_IIR_RDI ||
302	          (status & 0x0e) == UART_IIR_CTI)
303	        {
304	          uart_recvchars(dev);
305	        }
306	
307	      if ((status & 0x0e) == UART_IIR_THRI)
308	        {
309	          uart_xmitchars(dev);
310	        }
311	    }
312	
313	  return OK;
314	}
315	
316	static int up_ioctl(struct file *filep, int cmd, unsigned long arg)
317	{
318	  return -ENOTTY;
319	}
320	
321	static int up_receive(struct uart_dev_s *dev, uint32_t *status)
322	{
323	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
324	
325	  if (status)
326	    {
327	      *status = 0;
328	    }
329	
330	  return up_serialin(priv, UART_RBR_OFFSET) & 0xff;
331	}
332	
333	static void up_rxint(struct uart_dev_s *dev, bool enable)
334	{
335	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
336	  irqstate_t flags = enter_critical_section();
337	
338	  if (enable)
339	    {
340	#ifndef CONFIG_SUPPRESS_SERIAL_INTS
341	      priv->im |= UART_IER_ERBFI;
342	#endif
343	    }
344	  else
345	    {
346	      priv->im &= ~UART_IER_ERBFI;
347	    }
348	
349	  up_serialout(priv, UART_IER_OFFSET, priv->im);
350	  leave_critical_section(flags);
351	}
352	
353	static bool up_rxavailable(struct uart_dev_s *dev)
354	{
355	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
356	  return !!(up_serialin(priv, UART_LSR_OFFSET) & UART_LSR_DR);
357	}
358	
359	static void up_send(struct uart_dev_s *dev, int ch)
360	{
361	  struct up_dev_s *priv = (struct up_dev_s *)dev->priv;
