 *
 ****************************************************************************/

static int key2_open(void)
{
  char path[32];
  int fd;
  int ret;

  ret = pinctrl_set_gpio_function(KEY2_GPIO);
  if (ret < 0)
    {
      printf("[UART2] ERROR: pinctrl for KEY2 GPIO%d failed\n", KEY2_GPIO);
